import{_ as t,c as a,o as s,a5 as i}from"./chunks/framework.DorIfSpC.js";const o="/images/context7_mcp.png",C=JSON.parse('{"title":"Context7 MCP：讓 AI 程式助手不再寫出過時的程式碼","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/ai/context7-mcp-guide"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/ai/context7-mcp-guide"}],["meta",{"property":"og:title","content":"Context7 MCP：讓 AI 程式助手不再寫出過時的程式碼 | 星智未來"}],["meta",{"name":"twitter:title","content":"Context7 MCP：讓 AI 程式助手不再寫出過時的程式碼 | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Context7 MCP：讓 AI 程式助手不再寫出過時的程式碼\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/ai/context7-mcp-guide\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/ai/context7-mcp-guide\\"}}"]]},"headers":[],"relativePath":"ai/context7-mcp-guide.md","filePath":"ai/context7-mcp-guide.md","lastUpdated":1766391153000}'),n={name:"ai/context7-mcp-guide.md"};function l(p,e,r,d,c,h){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="context7-mcp-讓-ai-程式助手不再寫出過時的程式碼" tabindex="-1">Context7 MCP：讓 AI 程式助手不再寫出過時的程式碼 <a class="header-anchor" href="#context7-mcp-讓-ai-程式助手不再寫出過時的程式碼" aria-label="Permalink to &quot;Context7 MCP：讓 AI 程式助手不再寫出過時的程式碼&quot;">​</a></h1><p><strong>作者</strong>：Ray <strong>日期</strong>：2025 年 11 月</p><h2 id="痛點-llm-的訓練資料跟不上技術更新" tabindex="-1">痛點：LLM 的訓練資料跟不上技術更新 <a class="header-anchor" href="#痛點-llm-的訓練資料跟不上技術更新" aria-label="Permalink to &quot;痛點：LLM 的訓練資料跟不上技術更新&quot;">​</a></h2><p>使用 Claude Code、Cursor 或其他 AI 程式助手時，你是否遇過這些情況？</p><ul><li>AI 建議的 API 方法根本不存在</li><li>產生的程式碼用了舊版語法，跑起來一堆 deprecation warning</li><li>查了半天才發現 AI 給的範例是兩年前的版本</li></ul><p>這不是 AI 不夠聰明，而是 LLM 的訓練資料有時間差。像 Next.js、React Query、Tailwind 這類快速迭代的框架，官方文件可能每週都在更新，但 AI 學到的可能還是半年前的版本。</p><h2 id="context7-mcp-如何解決這個問題" tabindex="-1">Context7 MCP 如何解決這個問題 <a class="header-anchor" href="#context7-mcp-如何解決這個問題" aria-label="Permalink to &quot;Context7 MCP 如何解決這個問題&quot;">​</a></h2><p>Context7 是由 Upstash 開發的 MCP（Model Context Protocol）Server，它的做法很直接：</p><p><strong>在你發問的當下，即時抓取該函式庫的最新官方文件，注入到 AI 的 context 中。</strong></p><p>這意味著：</p><ul><li>文件版本對應你實際使用的版本</li><li>範例程式碼來自官方文件，不是 AI 自己編的</li><li>不需要切換視窗查文件，也不用擔心 hallucination</li></ul><h2 id="在-claude-code-中設定-context7" tabindex="-1">在 Claude Code 中設定 Context7 <a class="header-anchor" href="#在-claude-code-中設定-context7" aria-label="Permalink to &quot;在 Claude Code 中設定 Context7&quot;">​</a></h2><p>Claude Code 提供了簡潔的 CLI 指令來管理 MCP Server。以下是完整的操作流程：</p><h3 id="新增-context7-mcp-server" tabindex="-1">新增 Context7 MCP Server <a class="header-anchor" href="#新增-context7-mcp-server" aria-label="Permalink to &quot;新增 Context7 MCP Server&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> context7</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @upstash/context7-mcp@latest</span></span></code></pre></div><p>執行後會看到類似這樣的輸出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Added stdio MCP server context7 with command: npx -y @upstash/context7-mcp@latest to local config</span></span>
<span class="line"><span>File modified: /Users/ray/.claude.json [project: /Users/ray/sides/memobot]</span></span></code></pre></div><p>這會將 Context7 加入到當前專案的 local config 中。</p><h3 id="確認-mcp-server-狀態" tabindex="-1">確認 MCP Server 狀態 <a class="header-anchor" href="#確認-mcp-server-狀態" aria-label="Permalink to &quot;確認 MCP Server 狀態&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>系統會檢查 MCP Server 的健康狀態：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Checking MCP server health...</span></span>
<span class="line"><span>context7: npx -y @upstash/context7-mcp@latest - ✓ Connected</span></span></code></pre></div><p>看到 <code>✓ Connected</code> 就表示設定成功。</p><h3 id="移除-mcp-server" tabindex="-1">移除 MCP Server <a class="header-anchor" href="#移除-mcp-server" aria-label="Permalink to &quot;移除 MCP Server&quot;">​</a></h3><p>如果需要移除：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;context7&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local</span></span></code></pre></div><p><code>-s local</code> 參數表示只從當前專案的設定中移除，不影響全域設定。</p><p><img src="`+o+'" alt="Context7 MCP 運作示意圖"><em>圖：Context7 MCP 即時抓取最新文件並注入到 AI context 中</em></p><h2 id="實際使用方式" tabindex="-1">實際使用方式 <a class="header-anchor" href="#實際使用方式" aria-label="Permalink to &quot;實際使用方式&quot;">​</a></h2><p>設定完成後，在 Claude Code 中使用時只需要加上 <code>use context7</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>幫我用 Next.js 15 的 App Router 建立一個有 JWT 驗證的 middleware，use context7</span></span></code></pre></div><p>Context7 會自動：</p><ol><li>解析你提到的函式庫（Next.js）</li><li>抓取對應的最新文件</li><li>將相關文件注入到 prompt context 中</li></ol><p>你也可以設定 Claude Code 的規則，讓它自動在需要時使用 Context7：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Always use context7 when I need code generation, setup or configuration steps, or library/API documentation.</span></span></code></pre></div><h2 id="context7-提供的-mcp-tools" tabindex="-1">Context7 提供的 MCP Tools <a class="header-anchor" href="#context7-提供的-mcp-tools" aria-label="Permalink to &quot;Context7 提供的 MCP Tools&quot;">​</a></h2><p>Context7 MCP Server 提供兩個主要工具：</p><table tabindex="0"><thead><tr><th>Tool</th><th>功能</th><th>參數</th></tr></thead><tbody><tr><td><code>resolve-library-id</code></td><td>將函式庫名稱解析為 Context7 相容的 ID</td><td><code>libraryName</code>（必填）</td></tr><tr><td><code>get-library-docs</code></td><td>取得特定函式庫的文件</td><td><code>context7CompatibleLibraryID</code>（必填）、<code>topic</code>（選填）、<code>tokens</code>（選填，預設 5000）</td></tr></tbody></table><h2 id="進階設定-使用-api-key" tabindex="-1">進階設定：使用 API Key <a class="header-anchor" href="#進階設定-使用-api-key" aria-label="Permalink to &quot;進階設定：使用 API Key&quot;">​</a></h2><p>免費版有使用次數限制。如果需要更高的 rate limit 或存取私有 repository，可以到 <a href="https://context7.com/dashboard" target="_blank" rel="noreferrer">context7.com/dashboard</a> 申請 API Key：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> context7</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @upstash/context7-mcp@latest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --api-key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR_API_KEY</span></span></code></pre></div><h2 id="支援的開發環境" tabindex="-1">支援的開發環境 <a class="header-anchor" href="#支援的開發環境" aria-label="Permalink to &quot;支援的開發環境&quot;">​</a></h2><p>除了 Claude Code，Context7 MCP 也支援：</p><ul><li>Cursor</li><li>Windsurf</li><li>VS Code (Copilot)</li><li>Claude Desktop</li><li>Zed</li><li>Amazon Q Developer CLI</li><li>任何支援 MCP 協議的 AI 工具</li></ul><h2 id="小結" tabindex="-1">小結 <a class="header-anchor" href="#小結" aria-label="Permalink to &quot;小結&quot;">​</a></h2><p>Context7 MCP 解決了 AI 程式助手最常被詬病的問題：過時的訓練資料導致的錯誤建議。透過即時注入最新文件，它讓 AI 產生的程式碼更可靠、更符合當前版本的最佳實踐。</p><p>對於經常使用快速迭代框架的開發者來說，這是一個值得加入工具箱的 MCP Server。設定只需要一行指令，卻能省下大量 debug 和查文件的時間。</p><hr><p><strong>相關連結：</strong></p><ul><li><a href="https://github.com/upstash/context7" target="_blank" rel="noreferrer">Context7 GitHub Repository</a></li><li><a href="https://docs.anthropic.com/en/docs/claude-code" target="_blank" rel="noreferrer">Claude Code MCP 文件</a></li><li><a href="https://upstash.com/blog/context7-mcp" target="_blank" rel="noreferrer">Upstash 官方部落格</a></li></ul>',50)])])}const k=t(n,[["render",l]]);export{C as __pageData,k as default};
